{
  "decision-platform-wait-across-a-frequency-change": "WITH RECURSIVE arrival(platform_id, minute, close_min) AS (SELECT platform_id, open_min, close_min FROM platform_window WHERE open_min < close_min UNION ALL SELECT platform_id, minute + 1, close_min FROM arrival WHERE minute + 1 < close_min), totals AS (SELECT a.platform_id, COUNT(*) AS rider_count, SUM((SELECT MIN(t.depart_min) FROM train_call AS t WHERE t.platform_id = a.platform_id AND t.depart_min >= a.minute) - a.minute) AS wait_minutes FROM arrival AS a GROUP BY a.platform_id) SELECT w.platform_id, COALESCE(s.rider_count, 0) AS rider_count, COALESCE(s.wait_minutes, 0) AS wait_minutes FROM platform_window AS w LEFT JOIN totals AS s ON s.platform_id = w.platform_id ORDER BY w.platform_id",
  "decision-pooled-freight-booking": "SELECT e.quote_code AS east_quote, w.quote_code AS west_quote, (e.fee_cents - COALESCE(e.rebate_cents, 0)) + (w.fee_cents - COALESCE(w.rebate_cents, 0)) AS net_cents, e.advance_cents + w.advance_cents AS advance_cents FROM freight_quote AS e CROSS JOIN freight_quote AS w CROSS JOIN pool_limit AS p WHERE e.route_code = 'east' AND w.route_code = 'west' AND e.advance_cents + w.advance_cents <= p.cash_cents AND e.crew_slots + w.crew_slots <= p.slot_count ORDER BY net_cents, advance_cents, e.quote_code COLLATE BINARY, w.quote_code COLLATE BINARY LIMIT 1",
  "decision-portable-check-in-desk-dispatch": "WITH assignments AS (SELECT r.pod_id AS receiver, p.pod_id, p.entrants, p.fixed_desks + (p.pod_id = r.pod_id) AS desk_count FROM checkin_pod AS r CROSS JOIN checkin_pod AS p WHERE r.spare_socket = 1), times AS (SELECT receiver, pod_id, desk_count, entrants / desk_count + (entrants % desk_count <> 0) AS clear_min FROM assignments), winner AS (SELECT receiver FROM times GROUP BY receiver ORDER BY MAX(clear_min), SUM(clear_min), receiver COLLATE BINARY LIMIT 1) SELECT 'pod_id,desk_count,clear_min' || char(10) || group_concat(csv_line, '') AS csv_body FROM (SELECT pod_id || ',' || desk_count || ',' || clear_min || char(10) AS csv_line FROM times WHERE receiver = (SELECT receiver FROM winner) ORDER BY pod_id COLLATE BINARY)",
  "decision-post-crate-deposit-movements": "WITH movements AS (SELECT day_no, crate_count * deposit_cents - LAG(crate_count * deposit_cents, 1, 0) OVER (PARTITION BY lot_code ORDER BY feed_pos) AS change_cents FROM crate_image) SELECT day_no, SUM(change_cents) AS liability_change_cents FROM movements WHERE day_no BETWEEN 2 AND 4 GROUP BY day_no ORDER BY day_no"
}
